});

pm.test("Retorna a unidade de demonstração", function () {
    const resposta = pm.response.json();
    const unidade = resposta.content.find(
        item => item.codigoPublico === "RECIFE-CENTRO"
    );

    pm.expect(unidade).to.exist;
    pm.collectionVariables.set("idUnidade", unidade.idUnidade);
});

pm.test("Retorna status 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Cadastra produto ativo", function () {
    const resposta = pm.response.json();

    pm.expect(resposta.idProduto).to.exist;
    pm.expect(resposta.statusProduto).to.eql("ATIVO");

    pm.collectionVariables.set("idProduto", resposta.idProduto);
});

pm.test("Retorna status 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Registra entrada de 30 unidades", function () {
    const resposta = pm.response.json();

    pm.expect(resposta.tipoMovimentacao).to.eql("ENTRADA");
    pm.expect(resposta.quantidade).to.eql(30);
    pm.expect(resposta.saldoDisponivelAnterior).to.eql(0);
    pm.expect(resposta.saldoDisponivelPosterior).to.eql(30);
});

