});

pm.test("Retorna o saldo criado", function () {
    const resposta = pm.response.json();

    pm.expect(resposta.idUnidade).to.eql(
        pm.collectionVariables.get("idUnidade")
    );
    pm.expect(resposta.idProduto).to.eql(
        pm.collectionVariables.get("idProduto")
    );
    pm.expect(resposta.quantidadeDisponivel).to.eql(30);
    pm.expect(resposta.quantidadeReservada).to.eql(0);
    pm.expect(resposta.quantidadeParaVenda).to.eql(30);
});

